function getComments(source) {
  const commentRegex = new RegExp("^(.+) --- (.+)$");
  const commentsArray = getCodeBlockData(source, commentRegex).map((item) => {
    if (Array.isArray(item)) {
      return {
        time: Number(item[0]),
        content: String(item[1])
      };
    }
    return null;
  }).filter((item) => item !== null).sort((x, y) => x.time - y.time);
  return commentsArray;
}

